        v[0] = FastCos(FastAddRots(*(float *)(B + 0x158), a > 0.0f ? -1.0471976f : 1.0471976f)) * d;
        v[1] = FastSin(FastAddRots(*(float *)(B + 0x158), a > 0.0f ? -1.0471976f : 1.0471976f)) * d;
        v[2] = *(float *)(m + 0x18) - *(float *)(B + 0x148);
