    qcopy(m + 0x10, pos);
    *(int *)(m + 4) = col;
    m[9] = truncate_float_to_s32_r(4.0f) - 0x60;
    m[3] = (random_integer_below(100) < 0x14) ? 0x44 : 0x48;
    m[1] = 0;
    q = m + 0x20;
    *(int *)(m + 0xC) = 0;
    m[8] = func_001160D8();
    m[2] = *part_type11_textures;
    v.q = 0;
    v.f[0] = random_float_between(-1.0f, 1.0f);
    v.f[1] = random_float_between(-1.0f, 1.0f);
    v.f[2] = random_float_between(-1.0f, 1.0f);
    t.q = v.q;
    vec_scale_to_length(&t, &t, y);
    FastVecAdd(q, dir, &t);
    *(float *)(q + 0xC) = y * 0.75f;
    *(short *)(m + 0xA) = n;
    q[0x1B] = n;
    q[0x18] = b1A;
    *(float *)(q + 0x1C) = x;
    *(int *)(q + 0x10) = col;
    *(int *)(q + 0x14) = d;
